#!/usr/bin/env bash
# this_file: publish.sh
#
# Publish fontlab-python-pens: run ./release.sh (commit, tag, push, clean build), then
# ask GitHub Actions (.github/workflows/release.yml) to build the tag, cut a
# GitHub release and upload to pypi.org through Trusted Publishing. No PyPI
# token is needed locally. Waits for the run and checks pypi.org.
#
# Usage: ./publish.sh            # patch bump (arguments go to ./release.sh)
#        ./publish.sh minor
# Generated by pypitrust.

set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

./release.sh "$@"
TAG="$(git describe --tags --exact-match --match 'v[0-9]*.[0-9]*.[0-9]*' HEAD)"
VER="${TAG#v}"
REPO="$(gh repo view --json nameWithOwner -q .nameWithOwner)"

since="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "Publishing $REPO $TAG"
gh workflow run release.yml -R "$REPO" --ref "$TAG" -f tag="$TAG"

run=""
for _ in $(seq 1 30); do
  run="$(gh run list -R "$REPO" --workflow release.yml --event workflow_dispatch -L 10 \
    --json databaseId,headBranch,createdAt \
    -q "map(select(.headBranch == \"$TAG\" and .createdAt >= \"$since\"))[0].databaseId // empty")"
  [[ -n "$run" ]] && break
  sleep 2
done
if [[ -z "$run" ]]; then
  echo "error: no release.yml run appeared for $TAG; see gh run list -R $REPO" >&2
  exit 1
fi
gh run watch "$run" -R "$REPO" --exit-status

for _ in $(seq 1 30); do
  if curl -fsS -o /dev/null "https://pypi.org/pypi/fontlab-python-pens/$VER/json"; then
    echo "fontlab-python-pens $VER is on pypi.org: https://pypi.org/project/fontlab-python-pens/$VER/"
    exit 0
  fi
  sleep 10
done
echo "error: fontlab-python-pens $VER is not on pypi.org yet" >&2
exit 1
